entries[190186] = { ["name"] = "Holzstatuette", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Ruft mit dem Beschwörungskreis einen Inkubus herbei. (3 Min Abklingzeit)\n\"In den Sockel ist etwas graviert: Ich bin wieder zu Hause.\"" }
