entries[190307] = { ["name"] = "Nicht angezündete Fackel", ["text"] = "Herbeigezauberter Gegenstand\nQuestgegenstand\nEinzigartig\nBenutzen: In der Nähe eines Feuers anzünden.\n\"Wisst Ihr, was diese Fackel gebrauchen könnte? Eine Flamme.\"" }
entries[190308] = { ["name"] = "Brennende Fackel", ["text"] = "Herbeigezauberter Gegenstand\nQuestgegenstand\nEinzigartig\nDauer: 5 min\nBenutzen: Wirft eine Fackel auf die Zielposition und entzündet ein Feuer.\n\"Nützlich, um für feurige Ablenkung zu sorgen!\"" }
