entries[191061] = { ["name"] = "Brillantes Glas", ["text"] = "\"Im Inneren befindet sich etwas Glänzendes...\"\n<Zum Öffnen rechtsklicken>" }
entries[194101] = { ["name"] = "Netherwelpenhalsband", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Rechtsklicken, um den Netherdrachenwelpen zu beschwören und freizugeben." }
entries[260221] = { ["name"] = "Umarmung der Naaru", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Bringt Euch zurück nach: Ruhestein-Ort. Sprecht mit einem Gastwirt an einem anderen Ort, um Euren Heimatort zu ändern." }
entries[260433] = { ["name"] = "Halsband des Sternensplitterwelplings", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Mit Rechtsklick Euren Sternensplitterwelpling beschwören oder wieder freigeben." }
entries[260438] = { ["name"] = "Himmelblauer Phasenjäger", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\nBenötigt Stufe 30\nBenötigt Reiten (75)\nBenutzen: (3 Sek. Abklingzeit)\n\"Nach langer Ruh, in einer Welt entfacht, kommt die Zeit nun, dass er wieder erwacht.\"" }
entries[260622] = { ["name"] = "Replik der Exodar", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Beschwört eine Replik der Exodar, die neben Euch herfliegt. (3 Sek. Abklingzeit)" }
entries[260759] = { ["name"] = "Sternensplitternetherdrache", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\nBenötigt Stufe 70\nBenötigt Reiten (75)\nBenutzen: Beschwört einen reitbaren Sternensplitternetherdrachen oder gibt ihn frei. Das ist ein sehr schnelles Reittier. Dieses Reittier kann nur in der Scherbenwelt beschworen werden. (3 Sek. Abklingzeit)" }
